CREATE ROLE anon;
CREATE ROLE authenticated;
CREATE ROLE oxygen_workflow_worker;
CREATE SCHEMA oxygen_private;
CREATE SCHEMA auth;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$SELECT nullif(current_setting('request.jwt.claim.sub',true),'')::uuid$$;
CREATE TABLE auth.users(id uuid PRIMARY KEY, instance_id uuid, aud text, role text, email text, encrypted_password text, email_confirmed_at timestamptz, created_at timestamptz, updated_at timestamptz, raw_app_meta_data jsonb, raw_user_meta_data jsonb);
CREATE TABLE public.merchants(id uuid PRIMARY KEY,user_id uuid,email text,business_name text,slug text);
CREATE TABLE public.customers(id uuid PRIMARY KEY,merchant_id uuid,user_id uuid,first_name text,last_name text,email text);
CREATE TABLE public.orders(id uuid PRIMARY KEY,merchant_id uuid,customer_id uuid,order_number text,total numeric,currency text,payment_status text);
CREATE TABLE public.oxygen_workflows(id uuid PRIMARY KEY,order_id uuid,merchant_id uuid,customer_id uuid,stage text NOT NULL DEFAULT 'application_required');
CREATE TABLE oxygen_private.commands(id uuid PRIMARY KEY,workflow_id uuid,idempotency_key uuid,expected_version integer,channel text,command jsonb,status text);
CREATE TABLE oxygen_private.provider_states(workflow_id uuid PRIMARY KEY,state jsonb);
CREATE TABLE public.oxygen_form_drafts(workflow_id uuid PRIMARY KEY,user_id uuid NOT NULL,ciphertext text NOT NULL CHECK(length(ciphertext) BETWEEN 32 AND 16384),version integer NOT NULL DEFAULT 1,mutation_id uuid NOT NULL,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now(),expires_at timestamptz DEFAULT now()+interval '7 days');
ALTER TABLE public.oxygen_form_drafts ENABLE ROW LEVEL SECURITY;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.oxygen_form_drafts TO authenticated;
CREATE POLICY draft_user ON public.oxygen_form_drafts FOR ALL TO authenticated USING (user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
GRANT USAGE ON SCHEMA auth TO authenticated;
GRANT EXECUTE ON FUNCTION auth.uid() TO authenticated;
CREATE FUNCTION public.oxygen_form_draft_revision_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP='UPDATE' AND NEW.version<>OLD.version+1 THEN RAISE EXCEPTION 'Invalid draft revision'; END IF; RETURN NEW; END $$;
CREATE TRIGGER oxygen_form_draft_revision BEFORE INSERT OR UPDATE ON public.oxygen_form_drafts FOR EACH ROW EXECUTE FUNCTION public.oxygen_form_draft_revision_guard();
CREATE FUNCTION oxygen_private.purge_completed_address_draft() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER AS $$BEGIN IF NEW.state->'kyc'->>'address_status'='DONE' AND EXISTS(SELECT 1 FROM public.oxygen_workflows w WHERE w.id=NEW.workflow_id AND w.stage<>'application_required') THEN DELETE FROM public.oxygen_form_drafts WHERE workflow_id=NEW.workflow_id; END IF; RETURN NEW; END$$;
CREATE TRIGGER oxygen_purge_draft_on_address_done AFTER INSERT OR UPDATE OF state ON oxygen_private.provider_states FOR EACH ROW EXECUTE FUNCTION oxygen_private.purge_completed_address_draft();
